public BackOffPolicy build() {
    // Use an exponential back-off when a multiplier (or its supplier) is configured.
    if ((this.multiplier != null && this.multiplier > 0) || this.multiplierSupplier != null) {
        ExponentialBackOffPolicy policy;
        if (Boolean.TRUE.equals(this.random)) {
            policy = new ExponentialRandomBackOffPolicy();
        }
        else {
            policy = new ExponentialBackOffPolicy();
        }
        if (this.delay != null) {
            policy.setInitialInterval(this.delay);
        }
        if (this.delaySupplier != null) {
            policy.initialIntervalSupplier(this.delaySupplier);
        }
        if (this.multiplier != null) {
            policy.setMultiplier(this.multiplier);
        }
        if (this.multiplierSupplier != null) {
            policy.multiplierSupplier(this.multiplierSupplier);
        }
        // Previously we compared maxDelay with delay before setting;
        // now, if a maxDelay was explicitly provided, we always set it.
        if (this.maxDelay != null) {
            policy.setMaxInterval(this.maxDelay);
        }
        if (this.maxDelaySupplier != null) {
            policy.maxIntervalSupplier(this.maxDelaySupplier);
        }
        if (this.sleeper != null) {
            policy.setSleeper(this.sleeper);
        }
        return policy;
    }

    // Use a uniform random back-off only if both a delay and a higher maxDelay are provided.
    if (this.maxDelay != null && this.delay != null && this.maxDelay > this.delay) {
        UniformRandomBackOffPolicy policy = new UniformRandomBackOffPolicy();
        if (this.delay != null) {
            policy.setMinBackOffPeriod(this.delay);
        }
        if (this.delaySupplier != null) {
            policy.minBackOffPeriodSupplier(this.delaySupplier);
        }
        if (this.maxDelay != null) {
            policy.setMaxBackOffPeriod(this.maxDelay);
        }
        if (this.maxDelaySupplier != null) {
            policy.maxBackOffPeriodSupplier(this.maxDelaySupplier);
        }
        if (this.sleeper != null) {
            policy.setSleeper(this.sleeper);
        }
        return policy;
    }

    // Otherwise, fallback to a fixed back-off policy.
    FixedBackOffPolicy policy = new FixedBackOffPolicy();
    if (this.delay != null) {
        policy.setBackOffPeriod(this.delay);
    }
    if (this.sleeper != null) {
        policy.setSleeper(this.sleeper);
    }
    return policy;
}
