                buf.readUnsignedShort();
                buf.readUnsignedInt();
                buf.readUnsignedShort();
                position.set(Position.KEY_FUEL_USED, buf.readUnsignedShort() * 0.01);
                break;
            case 0x94:
                if (length > 0) {
                    position.set(Position.KEY_VIN, buf.readCharSequence(length, StandardCharsets.US_ASCII).toString());
