    if (!evaluators.get(sz - 1).matches(root, element))
        return false;

    // Now, work backwards through the evaluators. For each one, move up the 
    // ancestry (possibly skipping several levels) until we find one that matches.
    // If we reach the root without a match, then the candidate does not match.
    for (int i = sz - 2; i >= 0; i--) {
        element = element.parent();
        if (element == null)
            return false;
        while (!evaluators.get(i).matches(root, element)) {
            if (element == root)
                return false;
            element = element.parent();
            if (element == null)
                return false;
        }
    }
    return true;
}

@Override
public boolean matches(Element root, Element element) {
    // Start with the candidate element and work backwards through the evaluators.
    int i = evaluators.size() - 1;
    if (!evaluators.get(i).matches(root, element))
        return false;
    // Walk up the chain for the remaining evaluators.
    while (i > 0) {
        // Move to the candidate’s parent.
        element = element.parent();
        // For descendant combinators, keep climbing until we find an ancestor that matches.
        while (element != null && !evaluators.get(i - 1).matches(root, element)) {
            element = element.parent();
        }
        if (element == null)
            return false;
        i--;
    }
    return true;
}

@Override
public boolean matches(Element root, Element element) {
    // the last evaluator must match the element itself
    int size = evaluators.size();
    if (!evaluators.get(size - 1).matches(root, element))
        return false;
    // for each previous evaluator, walk up the ancestry until we find a match
    for (int i = size - 2; i >= 0; i--) {
        element = element.parent();
        while (element != null && !evaluators.get(i).matches(root, element)) {
            element = element.parent();
        }
        if (element == null)
            return false;
    }
    return true;
}

@Override
public boolean matches(Element root, Element element) {
    // When using a selector on an element ("context"),
    // the context element itself should not be considered.
    if (element == root)
        return false;
    int size = evaluators.size();
    // The last evaluator in the chain must directly match the candidate element.
    if (!evaluators.get(size - 1).matches(root, element))
        return false;
    // For each remaining evaluator, work upward in the ancestry until a match is found.
    for (int i = size - 2; i >= 0; i--) {
        // Step one level up.
        element = element.parent();
        if (element == null || element == root)
            return false;
        // For descendant combinators, it’s allowed to skip levels:
        while (!evaluators.get(i).matches(root, element)) {
            element = element.parent();
            if (element == null || element == root)
                return false;
        }
    }
    return true;
}

