Below is one acceptable fixed version of the function. (In this fix the indent is only applied for non‐first nodes – for example, when the previous sibling is a <br>, the text will be indented, but the very first text node will not.)

------------------------------------------------
/* Fixed version */
void outerHtmlHead(Appendable accum, int depth, Document.OutputSettings out) throws IOException {
    final boolean prettyPrint = out.prettyPrint();
    final Element parent = (parentNode instanceof Element) ? (Element) parentNode : null;
    final boolean normaliseWhite = prettyPrint && !Element.preserveWhitespace(parentNode);

    // Only trim leading whitespace if this is the first child of a block or a Document.
    boolean trimLeading = (siblingIndex == 0 && parent != null && parent.tag().isBlock())
            || (parentNode instanceof Document);
    boolean trimTrailing = nextSibling() == null && parent != null && parent.tag().isBlock();

    if (normaliseWhite) {
        // If this text is only whitespace and the next node will force an indent, skip output.
        Node next = this.nextSibling();
        boolean couldSkip = (next instanceof Element && ((Element) next).shouldIndent(out))
                || (next instanceof TextNode && ((TextNode) next).isBlank());
        if (couldSkip && isBlank())
            return;

        // Only indent if this is not the first child. In particular, if the text follows a <br>
        // element, force an indent so that wrapped text is on a new line.
        if (!isBlank() && siblingIndex > 0) {
            Node prev = previousSibling();
            if (prev instanceof Element && ((Element) prev).tag().getName().equals("br"))
                indent(accum, depth, out);
            else if (out.outline())
                indent(accum, depth, out);
        }
    }

    Entities.escape(accum, coreValue(), out, false, normaliseWhite, trimLeading, trimTrailing);
}
