private Position decodeTransparent(DeviceSession deviceSession, ByteBuf buf) {

    int type = buf.readUnsignedByte();

    if (type == 0xF0) {
        Position position = new Position(getProtocolName());
        position.setDeviceId(deviceSession.getDeviceId());

        Date time = readDate(buf, deviceSession.get(DeviceSession.KEY_TIMEZONE));

        // In the original code two separate bytes were read:
        //   one for the archive flag and one for the vehicle type,
        // but in fact these two pieces of information are packed into a single byte.
        // Reading an extra byte misaligns the buffer and causes coordinate values to be decoded incorrectly.
        int status = buf.readUnsignedByte();
        if (status > 0) {
            position.set(Position.KEY_ARCHIVE, true);
        }

        int subtype = buf.readUnsignedByte();
        switch (subtype) {
