        position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.1);
        buf.readUnsignedInt(); // area id (ignored)
        position.set(Position.KEY_RSSI, buf.readUnsignedByte());
        // Skip any remaining bytes from the fixed block (usually 2 extra bytes, so that a total of 20 bytes are consumed)
        buf.readerIndex(fixedBlockEnd);
    }

