Below is one acceptable fixed version. The problem was that the “alarm” field was read as a 2‐byte value rather than 1 byte (leaving the 6–byte gyro field unread). The fix is to read alarm with readUnsignedByte() and then, if 6 or more bytes remain, read exactly 6 bytes (and convert them to a hex string) for the “gyro” attribute.

Below is the fixed function:

------------------------------------------------

private Position decodeLocation2(DeviceSession deviceSession, ByteBuf buf, int type) {

    Position position = new Position(getProtocolName());
    position.setDeviceId(deviceSession.getDeviceId());

    Jt600ProtocolDecoder.decodeBinaryLocation(buf, position);
    position.setValid(type != MSG_LOCATION_REPORT_BLIND);

    position.set(Position.KEY_RSSI, buf.readUnsignedByte());
    position.set(Position.KEY_SATELLITES, buf.readUnsignedByte());
    position.set(Position.KEY_ODOMETER, buf.readUnsignedInt() * 1000L);

    int battery = buf.readUnsignedByte();
    if (battery <= 100) {
        position.set(Position.KEY_BATTERY_LEVEL, battery);
    } else if (battery == 0xAA) {
        position.set(Position.KEY_CHARGE, true);
    }

    position.setNetwork(new Network(CellTower.fromCidLac(
            getConfig(), buf.readUnsignedInt(), buf.readUnsignedShort())));

    int product = buf.readUnsignedByte();
    int status = buf.readUnsignedShort();
    int alarm = buf.readUnsignedByte(); // was readUnsignedShort()

    if (product == 1 || product == 2) {
        if (BitUtil.check(alarm, 0)) {
            position.set(Position.KEY_ALARM, Position.ALARM_LOW_POWER);
        }
    } else if (product == 3) {
        position.set(Position.KEY_BLOCKED, BitUtil.check(status, 5));
        if (BitUtil.check(alarm, 1)) {
            position.set(Position.KEY_ALARM, Position.ALARM_LOW_POWER);
        }
        if (BitUtil.check(alarm, 2)) {
            position.set(Position.KEY_ALARM, Position.ALARM_VIBRATION);
        }
        if (BitUtil.check(alarm, 3)) {
            position.set(Position.KEY_ALARM, Position.ALARM_LOW_BATTERY);
        }
    }

    position.set(Position.KEY_STATUS, status);

    // Read the gyro field (expected to be exactly 6 bytes)
    if (buf.readableBytes() >= 6) {
        byte[] gyroBytes = new byte[6];
        buf.readBytes(gyroBytes);
        StringBuilder hex = new StringBuilder();
        for (byte b : gyroBytes) {
            hex.append(String.format("%02x", b));
        }
        position.set("gyro", hex.toString());
    }

    return position;
}

