                    position.setValid(values[idx].equals("A"));
                }
                idx++;
                if (idx < values.length) {
                    String latStr = values[idx++];
                    if (latStr.length() > 1) {
                        double lat = Double.parseDouble(latStr.substring(1));
                        if (latStr.charAt(0) == 'S') {
                            lat = -lat;
                        }
                        position.setLatitude(lat);
                    }
