                if (!powerStr.isEmpty()) {
                    position.set(Position.KEY_POWER, Double.parseDouble(powerStr));
                }
                if (index < values.length) {
                    String batteryStr = values[index++];
                    if (!batteryStr.isEmpty()) {
                        position.set(Position.KEY_BATTERY, Double.parseDouble(batteryStr));
